{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Fees — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfd;--muted:#6b6f76;--accent:#6c5ce7;--accent-2:#00b894;--card:#fff;--glass:rgba(255,255,255,0.7);--mono:ui-monospace, SFMono-Regular, Menlo, Monaco, "Roboto Mono", monospace}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Arial,sans-serif;color:#222;background:linear-gradient(180deg,var(--bg),#f1f5f9);}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:transparent}
    .logo{font-weight:700;letter-spacing:0.6px}
    nav a{margin-left:18px;color:#333;text-decoration:none;font-size:15px}
    .wrap{max-width:980px;margin:28px auto;padding:26px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .intro{background:var(--card);padding:28px;border-radius:14px;box-shadow:0 8px 30px rgba(20,20,40,0.06)}
    .intro h1{margin:0 0 8px 0;font-size:22px;color:#111}
    .intro p{margin:0;color:var(--muted);line-height:1.45}
    .pattern{width:100%;height:120px;background:url('assets/img/pattern.svg') repeat;border-radius:10px;margin-top:16px}

    /* Comparator */
    .comp{background:linear-gradient(180deg,#fff, #fbfdff);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(30,30,60,0.04);}
    .toggle{display:flex;align-items:center;gap:12px;margin-bottom:12px}
    .switch{width:68px;height:34px;background:#e9eefb;border-radius:34px;padding:4px;display:flex;align-items:center;cursor:pointer}
    .knob{height:26px;width:26px;border-radius:50%;background:white;box-shadow:0 3px 8px rgba(30,30,60,0.12);transform:translateX(0);transition:transform .28s cubic-bezier(.2,.9,.2,1)}
    .switch[data-mode="packages"] .knob{transform:translateX(34px)}
    .prices{display:flex;flex-direction:column;gap:10px}
    .plan{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#fafbff);}
    .plan .label{font-weight:600}
    .plan .price{font-family:var(--mono);font-weight:700;color:var(--accent);font-size:20px}
    .small{font-size:13px;color:var(--muted)}

    .cta-wrap{margin-top:12px}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:white;text-decoration:none}

    /* Mood-to-Method */
    .mood{margin-top:18px;background:linear-gradient(180deg,#fff,#fefffb);padding:14px;border-radius:12px}
    .mood .opts{display:flex;gap:8px;flex-wrap:wrap}
    .mood button{padding:8px 10px;border-radius:8px;border:1px solid #eef;background:white;cursor:pointer}
    .mood .meta{margin-top:12px}
    .method{padding:10px;border-radius:8px;background:linear-gradient(90deg,#fbfbff,#fff);}
    .method h4{margin:0 0 6px 0}
    .note{font-size:13px;color:var(--muted);margin-top:10px}

    footer{margin-top:28px;font-size:13px;color:var(--muted)}

    @media (max-width:880px){.hero{grid-template-columns:1fr}.pattern{height:88px}}
  </style>
</head>
<body>
  <header>
    <div class="logo">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Overview</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Invest</a>
      <a href="book.html">Start</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="hero">
      <section class="intro">
        <h1>Costs & options shaped around steady progress</h1>
        <p>I aim to make access clear: single sessions, short focused packages, and ongoing support. Use the toggle to compare monthly continuity versus bundled packages; numbers animate so you can feel the difference.
        </p>
        <div class="pattern" aria-hidden="true"></div>
      </section>

      <aside class="comp" aria-labelledby="pricing-heading">
        <div class="toggle" id="pricing-toggle">
          <div style="font-size:13px;color:var(--muted)">Monthly</div>
          <div class="switch" data-mode="monthly" role="button" aria-pressed="false" tabindex="0">
            <div class="knob"></div>
          </div>
          <div style="font-size:13px;color:var(--muted)">Packages</div>
        </div>

        <div class="prices" id="prices">
          <div class="plan" data-base="140">
            <div>
              <div class="label">Guided Session</div>
              <div class="small">Single 50-minute session</div>
            </div>
            <div class="price" data-anim>---</div>
          </div>

          <div class="plan" data-base="600">
            <div>
              <div class="label">Resilience Series</div>
              <div class="small">5-session bundle for momentum</div>
            </div>
            <div class="price" data-anim>---</div>
          </div>

          <div class="plan" data-base="2200">
            <div>
              <div class="label">Steady Care Monthly</div>
              <div class="small">Weekly session and check-ins</div>
            </div>
            <div class="price" data-anim>---</div>
          </div>
        </div>

        <div class="cta-wrap">
          <a id="primary-cta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <div class="mood" aria-live="polite">
          <div style="font-size:13px;color:var(--muted);margin-bottom:8px">How are you feeling right now?</div>
          <div class="opts">
            <button data-mood="overwhelmed">Overwhelmed</button>
            <button data-mood="stuck">Stuck</button>
            <button data-mood="anxious">Anxious</button>
            <button data-mood="numb">Numb</button>
            <button data-mood="curious">Curious</button>
          </div>

          <div class="meta">
            <div class="method" id="method">
              <h4>Recommended: Guided Session</h4>
              <div class="small">A single 50-minute appointment to clarify priorities and plan next steps.</div>
            </div>
            <div class="note">Sessions and packages are clinical services; no specific outcomes are promised. Payment details and scheduling are confirmed at booking.</div>
          </div>
        </div>
      </aside>
    </div>

    <footer>
      <p>Confidentiality: Sessions are private and clinical notes are held in a secure manner. Scope: My services are psychotherapy and coaching-oriented; they are not emergency services. If you are in crisis or feel you may be a danger to yourself or others, call local emergency services or {{PHONE}}. For urgent risk, please use emergency channels — I cannot provide crisis response via email.</p>
    </footer>
  </main>

  <script>
    // Pricing comparator with animated numbers
    const switchEl = document.querySelector('.switch');
    const prices = document.querySelectorAll('[data-anim]');
    const plans = document.querySelectorAll('.plan');
    const cta = document.getElementById('primary-cta');

    function formatMoney(n){ return n.toLocaleString(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}); }

    function animateValue(el, start, end, duration=600){
      const startTime = performance.now();
      function tick(now){
        const t = Math.min(1,(now - startTime)/duration);
        const val = Math.round(start + (end - start) * (1 - Math.cos(t * Math.PI))/2);
        el.textContent = formatMoney(val);
        if(t < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    function updatePrices(mode){
      plans.forEach(plan=>{
        const base = Number(plan.getAttribute('data-base'));
        let target = base;
        if(mode === 'monthly'){
          // monthly: base is per-session or monthly total
          if(base > 1000){ target = Math.round(base / 4); } // show per-weekish for monthly product
          else target = base;
        } else {
          // packages: apply discounts
          if(base < 200) target = Math.round(base * 1); // single session shows same
          else if(base < 1000) target = Math.round(base * 0.9); // small discount
          else target = Math.round(base * 0.85); // larger bundles discounted
        }
        animateValue(plan.querySelector('[data-anim]'), Number(plan.querySelector('[data-anim]').textContent.replace(/[^0-9]/g, '')||0), target);
      });

      // change CTA phrasing
      if(mode === 'monthly') cta.textContent = 'Begin ongoing care';
      else cta.textContent = 'Reserve a package';
    }

    // initialize
    prices.forEach(p=>p.textContent = '$0');
    updatePrices('monthly');

    function toggleMode(newMode){
      switchEl.setAttribute('data-mode', newMode === 'packages' ? 'packages' : 'monthly');
      switchEl.setAttribute('aria-pressed', newMode === 'packages');
      updatePrices(newMode);
    }

    switchEl.addEventListener('click', ()=>{
      const newMode = switchEl.getAttribute('data-mode') === 'monthly' ? 'packages' : 'monthly';
      toggleMode(newMode);
    });
    switchEl.addEventListener('keydown', (e)=>{ if(e.key === 'Enter' || e.key === ' ') { e.preventDefault(); switchEl.click(); } });

    // Mood-to-Method: morph method card and update CTA label dynamically
    const moodButtons = document.querySelectorAll('[data-mood]');
    const methodEl = document.getElementById('method');
    const moodMap = {
      overwhelmed: {title:'Short Stabilization', desc:'Two focused sessions to reduce immediate distress and form a short plan.' ,cta:'Book stabilization'},
      stuck: {title:'Momentum Bundle', desc:'A 5-session plan to explore barriers and build a step-by-step routine.', cta:'Reserve momentum'},
      anxious: {title:'Breathing & Grounding', desc:'Session work focused on immediate regulation and skills to manage anxiety.', cta:'Start regulation work'},
      numb: {title:'Reconnect Sessions', desc:'Gentle pacing to notice feeling and rebuild engagement at your rhythm.', cta:'Begin reconnecting'},
      curious: {title:'Exploratory Session', desc:'A single meeting to identify goals and test next steps.', cta:'Try an exploratory session'}
    };

    moodButtons.forEach(btn=>{
      btn.addEventListener('click', ()=>{
        moodButtons.forEach(b=>b.disabled=false);
        btn.disabled = true;
        const m = btn.getAttribute('data-mood');
        const data = moodMap[m] || moodMap['curious'];
        methodEl.querySelector('h4').textContent = 'Recommended: ' + data.title;
        methodEl.querySelector('.small').textContent = data.desc;
        cta.textContent = data.cta;
      });
    });
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#6b6f76;--accent:#ff7ab6}
    body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:linear-gradient(180deg,#fff,#fbfdff);color:#1b1b1b}
    header{padding:18px 26px;display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:16px;color:#333;text-decoration:none}
    main{max-width:860px;margin:18px auto;padding:20px}
    h1{margin:4px 0 18px 0}
    .faq-list{display:grid;gap:10px}
    .q{background:#fff;padding:14px;border-radius:10px;box-shadow:0 6px 20px rgba(30,30,60,0.04)}
    .q button{display:flex;justify-content:space-between;width:100%;background:transparent;border:0;padding:0;text-align:left;font-size:16px}
    .a{margin-top:8px;color:var(--muted);display:none}
    .a.open{display:block}
    .clinical{margin-top:18px;padding:12px;background:linear-gradient(180deg,#fff,#fffaf3);border-radius:10px}
    .small{font-size:13px;color:var(--muted)}
    .mood-mini{margin-top:14px;display:flex;gap:8px}
    .mood-mini button{padding:8px 10px;border-radius:8px;border:1px solid #eee;background:white}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Intro</a>
      <a href="about.html">Background</a>
      <a href="fees.html">Invest</a>
      <a href="book.html">Begin</a>
    </nav>
  </header>

  <main>
    <h1>Questions people often ask</h1>

    <div class="faq-list" id="faq-list">
      <div class="q">
        <button aria-expanded="false"><span>What should I expect in a first session?</span><span aria-hidden="true">+</span></button>
        <div class="a">The first meeting is an opportunity to clarify why you’ve reached out, review history relevant to the concerns, and identify practical next steps. We’ll discuss what would be helpful and what you hope to get from sessions. Clinical notes are kept securely.</div>
      </div>

      <div class="q">
        <button aria-expanded="false"><span>How long is a session and how often?</span><span aria-hidden="true">+</span></button>
        <div class="a">Typical sessions are 50 minutes. Frequency varies by need: some people begin weekly, others benefit from biweekly or a short package of sessions. We’ll discuss rhythm that fits your life and goals.</div>
      </div>

      <div class="q">
        <button aria-expanded="false"><span>Do you accept insurance?</span><span aria-hidden="true">+</span></button>
        <div class="a">I provide a receipt you can submit to your insurer (superbill). Please check with your plan about out-of-network reimbursement. I do not bill insurers directly through this site.</div>
      </div>

      <div class="q">
        <button aria-expanded="false"><span>Is therapy confidential?</span><span aria-hidden="true">+</span></button>
        <div class="a">Yes: clinical work is confidential. Limits include risk of harm to self/others, suspicions of abuse of a vulnerable person, or court orders. Confidentiality details are reviewed at intake.</div>
      </div>

      <div class="q">
        <button aria-expanded="false"><span>What if I’m in crisis?</span><span aria-hidden="true">+</span></button>
        <div class="a">This practice does not provide crisis response. If you are in immediate danger or require urgent medical attention, call emergency services or a local crisis line. If you are within the U.S., you can call or text 988 for immediate support. For other urgent concerns, use local emergency channels.</div>
      </div>
    </div>

    <div class="clinical">
      <strong style="display:block;margin-bottom:8px">Clinical boundaries & confidentiality</strong>
      <div class="small">The services listed are psychotherapy and supportive counseling. They are not a substitute for emergency or medical services. Records and notes are kept in a secure, private system. If you have questions about limits of confidentiality or how records are stored, please ask during intake.</div>
    </div>

    <section style="margin-top:18px">
      <h2 style="margin-bottom:8px">Not sure what you need yet?</h2>
      <div class="small">Try the quick selector — choose how you feel, and get a short explanation of an approach that might fit.</div>
      <div class="mood-mini" id="mini-mood">
        <button data-mood="overwhelmed">Overwhelmed</button>
        <button data-mood="stuck">Stuck</button>
        <button data-mood="anxious">Anxious</button>
        <button data-mood="curious">Curious</button>
      </div>
      <div id="mini-reco" class="small" style="margin-top:10px">Select a mood to see a brief recommendation.</div>
    </section>

    <footer style="margin-top:18px;font-size:13px;color:var(--muted)">
      <p>Communication: Email exchanges are not intended for urgent matters. Response times vary; if you need faster support, call {{PHONE}}. For intake questions, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </footer>
  </main>

  <script>
    // Simple accordion
    document.querySelectorAll('.q button').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const a = btn.parentElement.querySelector('.a');
        const expanded = btn.getAttribute('aria-expanded') === 'true';
        btn.setAttribute('aria-expanded', String(!expanded));
        a.classList.toggle('open', !expanded);
      });
    });

    // Mini Mood-to-Method
    const moodMap = {
      overwhelmed: 'A short stabilization session to make immediate coping steps and small plans.',
      stuck: 'A series of focused meetings to explore obstacles and set actionable goals.',
      anxious: 'Skills-oriented sessions to reduce worry and improve tolerance for uncertainty.',
      curious: 'A single exploratory meeting to clarify goals and next steps.'
    };
    document.getElementById('mini-mood').addEventListener('click',(e)=>{
      const mood = e.target.getAttribute('data-mood');
      if(!mood) return;
      document.getElementById('mini-reco').textContent = moodMap[mood] || moodMap['curious'];
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#6b6f76;--accent:#3b82f6;--card:#fff}
    body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:linear-gradient(180deg,#f9fbff,#fff)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin-left:14px;color:#222;text-decoration:none}
    .hero{max-width:900px;margin:22px auto;padding:22px}
    .booking{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .panel{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(20,20,60,0.06)}
    .selector{display:flex;gap:8px;flex-wrap:wrap}
    .selector button{padding:10px 12px;border-radius:8px;border:1px solid #eef;background:white;cursor:pointer}
    .method-card{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfdff)}
    .book-form{display:flex;flex-direction:column;gap:10px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid #e6eef5}
    .book-btn{background:var(--accent);color:white;padding:10px 12px;border-radius:10px;text-decoration:none;text-align:center;display:inline-block}
    .small{font-size:13px;color:var(--muted)}
    .pattern-small{height:64px;background:url('assets/img/pattern.svg') repeat;border-radius:8px;margin-top:8px}
    @media (max-width:940px){.booking{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Bio</a>
      <a href="fees.html">Fees</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="hero">
    <h1 style="margin:0 0 10px 0">Begin a conversation</h1>
    <p class="small" style="margin:0 0 20px 0">Choose how you’re feeling — the guidance below will shape the suggested approach and the booking prompt.</p>

    <div class="booking">
      <section class="panel">
        <div style="font-size:14px;color:var(--muted)">Tell me your current state</div>
        <div class="selector" id="mood-select">
          <button data-mood="overwhelmed">Overwhelmed</button>
          <button data-mood="sad">Sad</button>
          <button data-mood="anxious">Anxious</button>
          <button data-mood="stuck">Stuck</button>
          <button data-mood="curious">Curious</button>
        </div>

        <div class="method-card" id="method-card" aria-live="polite">
          <h3 id="method-title">Exploratory Session</h3>
          <p id="method-desc" class="small">A single 50-minute meeting to understand what matters now and identify next steps that feel manageable.</p>
          <div class="pattern-small" aria-hidden="true"></div>
        </div>

        <div class="small" style="margin-top:10px">Note: I cannot provide crisis services via this site. If you are in immediate danger, contact local emergency services or a crisis line.</div>
      </section>

      <aside class="panel">
        <form id="booking-form" class="book-form" action="{{PRIMARY_CTA_URL}}" method="get">
          <label class="small">Preferred contact</label>
          <input name="email" type="email" placeholder="Email, e.g. you@example.com" required>

          <label class="small">Phone (optional)</label>
          <input name="phone" placeholder="{{PHONE}}" aria-label="Phone">

          <label class="small">Preferred session type</label>
          <select name="service">
            <option value="explore">Exploratory Session — 50 minutes</option>
            <option value="series">Resilience Series — 5 sessions</option>
            <option value="monthly">Steady Care — weekly</option>
          </select>

          <label class="small">What feels most important to address?</label>
          <textarea name="note" rows="4" placeholder="A line about what brought you here (optional)"></textarea>

          <input type="hidden" name="source" value="website-booking">

          <button id="book-btn" class="book-btn" type="submit">Schedule an exploratory session</button>

          <div class="small" style="margin-top:8px">I aim to respond within a few business days. If your need is urgent, call local services or use crisis resources. By booking, you agree to discuss confidentiality and standard practice policies at intake.</div>
        </form>
      </aside>
    </div>

    <section style="margin-top:18px" class="panel">
      <h3 style="margin:0 0 8px 0">Practical details</h3>
      <div class="small">Sessions are typically 50 minutes. Cancellations appreciated at least 48 hours in advance when possible; late cancellations may be charged. If you have questions about fees, privacy, or scope, please email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}.</div>
    </section>
  </main>

  <script>
    // Mood-to-Method with CTA morphing
    const moodSelect = document.getElementById('mood-select');
    const methodTitle = document.getElementById('method-title');
    const methodDesc = document.getElementById('method-desc');
    const bookBtn = document.getElementById('book-btn');

    const map = {
      overwhelmed: {title:'Short Stabilization', desc:'Two focused sessions to reduce immediate distress and form a brief safety and coping plan.', cta:'Book stabilization'},
      sad: {title:'Supportive Sessions', desc:'Gentle, paced work to make space for feeling and to consider next steps.', cta:'Schedule support'},
      anxious: {title:'Skills-Focused Session', desc:'Targeted strategies to manage worry and build tolerable routines.', cta:'Start skills work'},
      stuck: {title:'Momentum Bundle', desc:'A multi-session plan to examine barriers and make practical changes.', cta:'Reserve a series'},
      curious: {title:'Exploratory Session', desc:'A single meeting to clarify goals and options.', cta:'Schedule an exploratory session'}
    };

    moodSelect.addEventListener('click',(e)=>{
      const btn = e.target.closest('button');
      if(!btn) return;
      // toggle visual
      moodSelect.querySelectorAll('button').forEach(b=>b.style.opacity=1);
      btn.style.opacity = 0.6;

      const m = btn.getAttribute('data-mood');
      const r = map[m] || map['curious'];

      // small morph animation
      methodTitle.style.opacity = 0; methodDesc.style.opacity = 0;
      setTimeout(()=>{
        methodTitle.textContent = r.title;
        methodDesc.textContent = r.desc;
        bookBtn.textContent = r.cta;
        methodTitle.style.opacity = 1; methodDesc.style.opacity = 1;
      },180);

      // also adapt hidden service selection if relevant
      const service = document.querySelector('select[name=service]');
      if(m === 'stuck') service.value = 'series';
      else if(m === 'overwhelmed') service.value = 'explore';
      else service.value = 'explore';
    });

    // Lightweight form interception to open primary CTA in new tab with query
    document.getElementById('booking-form').addEventListener('submit',(e)=>{
      // allow default GET to {{PRIMARY_CTA_URL}}; enhance analytics-friendly params
      // no client-side storage of sensitive content
    });
  </script>
</body>
</html>"} 
